    event.preventDefault()
    const activeValue = budgetDraft.activeMinutes.trim() === '' ? null : Number(budgetDraft.activeMinutes)
    const turnsValue = budgetDraft.turns.trim() === '' ? null : Number(budgetDraft.turns)
